function AdminConversation({thread,user,onSent}) {
  const latestMessageProjectId=thread.messages.at(-1)?.project_id;
  const brief=clientProjects(thread.client).find(project=>project.id===latestMessageProjectId)||latestClientProject(thread.client);
  const send=async({content,attachment})=>{if(!user||(!content.trim()&&!attachment))return {error:"Write a message or choose a file."};const s=getSupabaseBrowserClient();let attachments=[];if(attachment){const fileResult=await uploadChatFile(s,user.id,attachment);if(fileResult.error)return fileResult;attachments=[fileResult.data];}const {data,error}=await s.from("messages").insert({project_id:brief?.id||null,sender_id:user.id,recipient_id:thread.client.id,content:content.trim()||`Attached: ${attachment?.name||"file"}`,attachments}).select("id").single();if(!error){dispatchEmailEvent("new_message",data.id);await onSent();}return {error:error?.message};};
  return <><header className="mi-chat-header"><i>{initials(thread.client.full_name||thread.client.email)}</i><div><b>{thread.client.full_name||"No name provided"}</b><small>{thread.client.email}</small></div><span>{brief?title(brief.status):"Registered"}</span><a href="/admin">Open Action Center <ChevronRight size={14}/></a></header><ChatStream messages={thread.messages} currentUserId={user?.id} empty="No messages yet. Send a helpful first message."/><ChatComposer placeholder={`Message ${thread.client.full_name||"client"}…`} onSend={send}/></>;
}

function ChatStream({messages,currentUserId,empty}) { const endRef=useRef(null); useEffect(()=>{endRef.current?.scrollIntoView({block:"end"})},[messages.length]); let previousDay=""; return <div className="mi-chat-stream">{messages.length?messages.map(message=>{const day=new Date(message.created_at).toLocaleDateString(undefined,{month:"long",day:"numeric",year:"numeric"});const divider=day!==previousDay;previousDay=day;return <div key={message.id}>{divider&&<div className="mi-chat-day"><span>{day}</span></div>}<div className={cx("mi-chat-bubble-row",message.sender_id===currentUserId?"is-mine":"is-theirs")}><article className="mi-chat-bubble"><p>{message.content}</p>{Array.isArray(message.attachments)&&message.attachments.map(file=><ChatAttachment key={`${message.id}-${file.url}`} file={file}/>)}</article><time>{new Date(message.created_at).toLocaleTimeString([],{hour:"numeric",minute:"2-digit"})}</time></div></div>}):<ChatEmpty title="No messages yet" copy={empty}/>}<div ref={endRef}/></div>; }

function ChatAttachment({file}) { const [url,setUrl]=useState(""); const isImage=(file.type||"").startsWith("image/"); useEffect(()=>{let active=true;getSupabaseBrowserClient().storage.from("portal-files").createSignedUrl(file.url,3600).then(({data})=>{if(active)setUrl(data?.signedUrl||"")});return()=>{active=false}},[file.url]);return <a className={cx("mi-chat-file",isImage&&"is-image")} href={url||"#"} target="_blank" rel="noreferrer">{isImage&&url?<img src={url} alt={file.name}/>:<FileText size={17}/>}<span><b>{file.name}</b><small>{formatBytes(file.size)}</small></span></a>; }

function ChatComposer({placeholder,onSend}) {
  const [content,setContent]=useState(""); const [attachment,setAttachment]=useState(null); const [sending,setSending]=useState(false); const [error,setError]=useState(""); const ref=useRef(null);
  const submit=async()=>{if(sending)return;setSending(true);setError("");const result=await onSend({content,attachment});if(result?.error)setError(result.error);else{setContent("");setAttachment(null);if(ref.current)ref.current.value="";}setSending(false);};
  return <div className="mi-chat-composer"><textarea value={content} onChange={event=>setContent(event.target.value)} onKeyDown={event=>{if(event.key==="Enter"&&!event.shiftKey){event.preventDefault();submit();}}} placeholder={placeholder} rows={1}/>{attachment&&<div className="mi-chat-file-chip"><FileText size={14}/>{attachment.name}<button onClick={()=>setAttachment(null)} aria-label="Remove attachment"><X size={14}/></button></div>}<div><label className="mi-chat-attach"><Upload size={17}/><span>Attach</span><input ref={ref} hidden type="file" onChange={event=>setAttachment(event.target.files?.[0]||null)}/></label><small>Enter to send · Shift+Enter for a new line</small><button className="mi-chat-send" disabled={sending||(!content.trim()&&!attachment)} onClick={submit}><Send size={16}/>{sending?"Sending…":"Send"}</button></div>{error&&<p className="mi-chat-composer-error">{error}</p>}</div>;
}

function ChatEmpty({title,copy}) { return <div className="mi-chat-empty"><MessageCircle size={28}/><h3>{title}</h3><p>{copy}</p></div>; }
async function uploadChatFile(supabase,userId,file) { const path=`${userId}/messages/${crypto.randomUUID()}-${file.name.replace(/[^a-zA-Z0-9._-]/g,"-")}`;const {error}=await supabase.storage.from("portal-files").upload(path,file,{upsert:false});return error?{error:error.message}:{data:{name:file.name,url:path,size:file.size,type:file.type}}; }
async function getPrimaryAdmin(supabase) { const {data}=await supabase.rpc("primary_milink_admin_id"); return data||""; }
function formatBytes(bytes=0) { return bytes>1024*1024?`${(bytes/(1024*1024)).toFixed(1)} MB`:`${Math.max(1,Math.ceil(bytes/1024))} KB`; }
function relativeTime(value,now=Date.now()) { if(!value)return "";const seconds=Math.max(0,Math.floor((now-new Date(value).getTime())/1000));if(seconds<60)return "Just now";if(seconds<3600)return `${Math.floor(seconds/60)}m ago`;if(seconds<86400)return `${Math.floor(seconds/3600)}h ago`;if(seconds<172800)return "Yesterday";return new Date(value).toLocaleDateString(undefined,{month:"short",day:"numeric"}); }

