useEffect(()=>{setBrief(newProject?null:selectedBrief||null);setForm({...initial,...(!newProject&&selectedBrief?selectedBrief:{})});setStep(0);setNotice("");setErrors({});setSubmittedThisSession(false);dirty.current=false;},[selectedBrief?.id,newProject]);
